class Solution {
  public int minLights(int[] lights) {
    int n = lights.length;
    int[] diff = new int[n + 1];
    for (int i = 0; i < n; i++) {
      if (lights[i] > 0) {
        diff[Math.max(0, i - lights[i])]++;
        diff[Math.min(n - 1, i + lights[i]) + 1]--;
      }
    }
    int added = 0, cover = 0;
    boolean[] lit = new boolean[n];
    for (int i = 0; i < n; i++) {
      cover += diff[i];
      lit[i] = cover > 0;
    }
    for (int i = 0; i < n; ) {
      if (lit[i]) {
        i++;
        continue;
      }
      added++;
      i += 3;
    }
    return added;
  }
}
